import { Entity, PrimaryColumn, Column, CreateDateColumn, ManyToOne, JoinColumn } from 'typeorm';
import { User } from '../../user/entities/user.entity';

@Entity('vaults')
export class Vault {
  /** Generated by the client: the vault's keys and label are bound to it. */
  @PrimaryColumn('uuid')
  id: string;

  @Column({ name: 'created_by', type: 'uuid' })
  createdBy: string;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'created_by' })
  creator: User;

  /** Vault name encrypted under the vault key. The server cannot read it. */
  @Column({ name: 'label_encrypted', type: 'text', nullable: true })
  labelEncrypted: string | null;

  @Column({ name: 'label_nonce', type: 'text', nullable: true })
  labelNonce: string | null;

  @Column({ name: 'sort_order', type: 'int', default: 0 })
  sortOrder: number;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt: Date;
}
